<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">log4j.appender.A1</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">org.apache.log4j.DailyRollingFileAppender</span></span>
